public static void JuneMountainPalette(){EditorSceneManager.OpenScene(Scene);const string folder="Assets/_Anseong/Art/Environment/JuneMountains";Folder(folder);AssetDatabase.Refresh();var shader=Shader.Find("Universal Render Pipeline/Lit");if(!shader||ShaderUtil.ShaderHasError(shader))throw new Exception("Forest shader invalid");var material=new Material(shader){name="JuneForest_Green",enableInstancing=true};var existing=AssetDatabase.LoadAssetAtPath<Material>(folder+"/JuneForest_Green.mat");if(existing){Object.DestroyImmediate(material);material=existing;material.shader=shader;}else AssetDatabase.CreateAsset(material,folder+"/JuneForest_Green.mat");material.SetColor("_BaseColor",new Color(.23f,.37f,.16f));material.SetFloat("_Smoothness",0);EditorUtility.SetDirty(material);var terrain=GameObject.Find("ConnectedCoastalHinterland");if(!terrain)throw new Exception("Missing connected hinterland");var renderer=terrain.GetComponent<MeshRenderer>();renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;var slots=renderer.sharedMaterials;for(int i=0;i<slots.Length;i++)slots[i]=material;renderer.sharedMaterials=slots;File.WriteAllText(folder+"/README.md","# June mountain foliage\nConnected hinterland uses a matte standard URP Lit material, June-green Base Color. Shapes unchanged, no extra trees or textures. Adjust Base Color on JuneForest_Green.mat. Existing industrial paving, sand and water preserved. VR performance not measured.\n");AssetDatabase.SaveAssets();AssetDatabase.Refresh();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),Scene);ShaderUtil.allowAsyncCompilation=false;Shader.WarmupAllShaders();Capture(Camera.main,"JuneMountains_Main");var go=new GameObject("JuneMountainsPreview");var camera=go.AddComponent<Camera>();camera.CopyFrom(Camera.main);camera.transform.position=new Vector3(0,65,-120);camera.transform.rotation=Quaternion.Euler(-2,0,0);Capture(camera,"JuneMountains_RobotView");Object.DestroyImmediate(go);Debug.Log("JUNE_MOUNTAINS_PASS vegetationMaterial=true unchangedGeometry=true extraTrees=0 shaderErrors=0");}
